// Demo only: a small Postman Collection v2.1 built from the mock OpenAPI document (the real one is generated by
// tt-core, internal/contract/postman.go). One request per operation, base URL in {{baseUrl}}.

type Json = Record<string, unknown>;

export function postmanOf(service: string, doc: Json, baseUrl?: string): Json {
  const paths = (doc.paths ?? {}) as Record<string, Record<string, Json>>;
  const items: Json[] = [];
  for (const path of Object.keys(paths).sort()) {
    for (const [method, op] of Object.entries(paths[path])) {
      if (!['get', 'post', 'put', 'patch', 'delete'].includes(method)) continue;
      const segs = path.split('/').filter(Boolean).map((s) => (s.startsWith('{') ? `:${s.slice(1, -1)}` : s));
      const url: Json = { raw: `{{baseUrl}}/${segs.join('/')}`, host: ['{{baseUrl}}'], path: segs };
      const request: Json = { method: method.toUpperCase(), url, header: [{ key: 'Accept', value: 'application/json' }] };
      const content = ((op.requestBody ?? {}) as Json).content as Record<string, Json> | undefined;
      const ex = content?.['application/json']?.examples as Record<string, { value: unknown }> | undefined;
      const first = ex ? (ex.typical ?? Object.values(ex)[0]) : undefined;
      if (first) request.body = { mode: 'raw', raw: JSON.stringify(first.value, null, 2), options: { raw: { language: 'json' } } };
      items.push({ name: `${method.toUpperCase()} ${path}`, request });
    }
  }
  return {
    info: { name: service, description: 'Generated by traffic-twin from the inferred OpenAPI contract.', schema: 'https://schema.getpostman.com/json/collection/v2.1.0/collection.json' },
    item: items,
    variable: [{ key: 'baseUrl', value: baseUrl ?? `http://localhost:8480/__svc/${encodeURIComponent(service)}`, type: 'string' }],
  };
}
